so[tabla_uni$Variable == &quot;mag&quot;] a_mag &lt;- tabla_uni$Asimetria[tabla_uni$Variable == &quot;mag&quot;] La magnitud presenta asimetría positiva (+1.98) y curtosis +5.45: NO es gaussiana, es una distribución de tipo exponencial truncada en Mc = 5.0. Este resultado no es una anomalía del dato: es exactamente lo que predice la LEY DE GUTENBERG-RICHTER (sección 6.1.4), que establece que la frecuencia de sismos decae exponencialmente con la magnitud. Consecuencia metodológica: cualquier técnica que asuma normalidad de la magnitud (media ± desviación estándar, intervalos t de Student, regresión lineal ordinaria) está mal especificada. Se deben usar estimadores de máxima verosimilitud exponencial y estadística no paramétrica. 6.1.2 6.1.2 Visualización univariada: histograma normalizado + KDE + boxplot # Histograma normalizado + densidad de kernel + boxplot (plotly) para una variable. # Devuelve el gráfico y el porcentaje de atípicos según la regla de Tukey. panel_univariado &lt;- function(serie, nombre, unidad = &quot;&quot;, bins = 50, log_x = FALSE) { s &lt;- as.numeric(serie) s &lt;- s[is.finite(s)] # Regla de Tukey para atípicos (sobre la escala original) q &lt;- quantile(s, c(0.25, 0.75), names = FALSE) iqr &lt;- q[2] - q[1] lo &lt;- q[1] - 1.5 * iqr hi &lt;- q[2] + 1.5 * iqr n_out &lt;- sum(s &lt; lo | s &gt; hi) media &lt;- mean(s); mediana &lt;- median(s) asim &lt;- skewness(s); curt &lt;- kurtosis(s) - 3 etq_media &lt;- sprintf(&quot;Media = %.2f&quot;, media) etq_mediana &lt;- sprintf(&quot;Mediana = %.2f&quot;, mediana) # En escala logarítmica se grafica log10(x) para que los intervalos sean uniformes if (log_x) { x &lt;- log10(s[s &gt; 0]); x_media &lt;- log10(media); x_mediana &lt;- log10(mediana) } else { x &lt;- s; x_media &lt;- media; x_mediana &lt;- mediana } # Ancho de banda tipo Scott; si el IQR es 0 (p. ej. muchos ceros) bw.nrd da 0 y se usa bw.nrd0 bw &lt;- bw.nrd(x) if (!is.finite(bw) || bw &lt;= 0) bw &lt;- bw.nrd0(x) dens &lt;- density(x, bw = bw) h &lt;- hist(x, breaks = bins, plot = FALSE) ymax &lt;- max(c(h$density, dens$y)) * 1.05 p1 &lt;- plot_ly() %&gt;% add_histogram(x = x, histnorm = &quot;probability density&quot;, nbinsx = bins, name = &quot;Histograma&quot;, marker = list(color = AZUL, line = list(color = &quot;white&quot;, width = 0.3)), opacity = 0.9) %&gt;% add_lines(x = dens$x, y = dens$y, name = &quot;KDE&quot;, line = list(color = ROJO, width = 2.4)) %&gt;% add_lines(x = rep(x_media, 2), y = c(0, ymax), name = etq_media, line = list(color = VERDE, dash = &quot;dash&quot;, width = 2)) %&gt;% add_lines(x = rep(x_mediana, 2), y = c(0, ymax), name = etq_mediana, line = list(color = MORADO, dash = &quot;dashdot&quot;, width = 2)) %&gt;% layout(yaxis = list(title = &quot;Densidad&quot;)) p2 &lt;- plot_ly() %&gt;% add_boxplot(x = x, name = &quot; &quot;, boxpoints = &quot;outliers&quot;, showlegend = FALSE, marker = list(color = AZUL, size = 3, opacity = 0.35), line = list(color = AZUL), fillcolor = &quot;rgba(76,114,176,0.35)&quot;) fig &lt;- subplot(p1, p2, nrows = 2, heights = c(0.78, 0.22), shareX = TRUE, titleY = TRUE) %&gt;% layout(title = list(text = sprintf(&quot;%s — histograma normalizado + KDE (asimetría = %+.2f, curtosis = %+.2f)&quot;, nombre, asim, curt), font = list(size = 14)), xaxis2 = list(title = trimws(paste(nombre, unidad))), legend = list(orientation = &quot;h&quot;, y = -0.18), margin = list(t = 60)) list(fig = fig, pct = n_out / length(s) * 100, n_out = n_out, lo = lo, hi = hi) } Distribución de la magnitud u_mag &lt;- panel_univariado(base_uni$mag, &quot;Magnitud&quot;, &quot;(Mw)&quot;, bins = 45) u_mag$fig Bigotes de Tukey: [4.50 , 6.10] — atípicos: 4,006 (5.80 %). La magnitud decae monótonamente desde Mc = 5.0: hay órdenes de magnitud más sismos pequeños que grandes. El boxplot marca 5.80 % de observaciones como «atípicas» por la regla de Tukey, pero ese diagnóstico es incorrecto en este contexto: la regla de 1.5 × IQR supone simetría, y aquí la cola derecha es intrínseca al fenómeno físico. Un sismo de M 8.5 no es un error de medición ni un dato para eliminar: es precisamente el evento que más importa detectar. Decisión: no se eliminan magnitudes altas. Los valores extremos se tratan como señal, y la detección de anomalías se hará sobre la tasa de ocurrencia (conteos), no descartando eventos. Distribución de la profundidad u_prof &lt;- panel_univariado(base_uni$depth, &quot;Profundidad&quot;, &quot;(km)&quot;, bins = 70) u_prof$fig Bigotes de Tukey: [-43.50 , 121.30] — atípicos: 8,874 (12.84 %). modas &lt;- base_uni %&gt;% count(depth, sort = TRUE) %&gt;% slice_head(n = 5) cat(&quot;Valores más repetidos de profundidad:

